export const scriptTemplates: Record<string, string> = {
  "members-data.js": "const dccMembers = [];\n\nconst renderMembers = () => {\n  const section = document.querySelector(\"#council\");\n  const track = document.querySelector(\"[data-members-track]\");\n  const memberLinks = document.querySelectorAll('a[href=\"#council\"]');\n  if (!section || !track) return;\n\n  if (!dccMembers.length) {\n    section.hidden = true;\n    memberLinks.forEach((link) => { link.hidden = true; });\n    return;\n  }\n\n  const createSet = (hidden = false) => {\n    const set = document.createElement(\"div\");\n    set.className = \"logo-set\";\n    if (hidden) set.setAttribute(\"aria-hidden\", \"true\");\n    dccMembers.forEach((member) => {\n      const frame = document.createElement(\"span\");\n      const image = document.createElement(\"img\");\n      image.src = member.logo;\n      image.alt = hidden ? \"\" : member.logoAlt || member.name;\n      image.loading = \"lazy\";\n      frame.append(image);\n      set.append(frame);\n    });\n    return set;\n  };\n\n  track.replaceChildren(createSet());\n  if (dccMembers.length >= 4) {\n    track.append(createSet(true));\n  } else {\n    track.classList.add(\"is-static\");\n  }\n};\n\nrenderMembers();\n",
  "blog-data.js": "const dccBlogPosts = [];\n\nconst createBlogCard = (post, index) => {\n  const article = document.createElement(\"a\");\n  article.className = \"blog-card\";\n  article.href = `/blog/${encodeURIComponent(post.slug)}`;\n  article.style.setProperty(\"--blog-card-index\", index);\n\n  const imageWrap = document.createElement(\"div\");\n  imageWrap.className = \"blog-card-image\";\n\n  const image = document.createElement(\"img\");\n  image.src = post.image;\n  image.alt = post.imageAlt || \"\";\n  image.loading = index === 0 ? \"eager\" : \"lazy\";\n  imageWrap.append(image);\n\n  const content = document.createElement(\"div\");\n  content.className = \"blog-card-content\";\n\n  const label = document.createElement(\"p\");\n  label.className = \"blog-card-label\";\n  label.textContent = post.category || \"Coalition perspective\";\n\n  const title = document.createElement(\"h2\");\n  title.textContent = post.title;\n\n  const excerpt = document.createElement(\"p\");\n  excerpt.className = \"blog-card-excerpt\";\n  excerpt.textContent = post.excerpt;\n\n  const footer = document.createElement(\"div\");\n  footer.className = \"blog-card-footer\";\n\n  const date = document.createElement(\"p\");\n  date.textContent = `${post.date} · ${post.readingTime}`;\n\n  footer.append(date);\n  content.append(label, title, excerpt, footer);\n  article.append(imageWrap, content);\n\n  return article;\n};\n\nconst renderBlogPosts = () => {\n  const list = document.querySelector(\"#blog-post-list\");\n  if (!list) return;\n\n  const fragment = document.createDocumentFragment();\n  dccBlogPosts.forEach((post, index) => {\n    fragment.append(createBlogCard(post, index));\n  });\n  list.append(fragment);\n};\n\nrenderBlogPosts();\n",
  "blog-post.js": "const blogParams = new URLSearchParams(window.location.search);\nconst blogPathParts = window.location.pathname.split(\"/\").filter(Boolean);\nconst requestedPostSlug = blogParams.get(\"post\") ||\n  (blogPathParts[0] === \"blog\" && blogPathParts[1] ? decodeURIComponent(blogPathParts[1]) : null);\nconst selectedBlogPost =\n  dccBlogPosts.find((post) => post.slug === requestedPostSlug || post.previousSlugs?.includes(requestedPostSlug)) ||\n  dccBlogPosts[0];\n\nconst asBlogText = (value, fallback = \"\") =>\n  typeof value === \"string\" && value.trim() ? value : fallback;\n\nconst escapeBlogHtml = (value) =>\n  String(value || \"\")\n    .replaceAll(\"&\", \"&amp;\")\n    .replaceAll(\"<\", \"&lt;\")\n    .replaceAll(\">\", \"&gt;\")\n    .replaceAll('\"', \"&quot;\");\n\nconst legacyRichTextToHtml = (value) => {\n  if (!value || typeof value !== \"object\" || !Array.isArray(value.content)) {\n    return \"\";\n  }\n\n  return value.content\n    .map((node) => {\n      const text = Array.isArray(node?.content)\n        ? node.content.map((child) => child?.text || \"\").join(\"\")\n        : \"\";\n      if (!text.trim()) return \"\";\n      if (node.type === \"heading\") {\n        const level = node.attrs?.level === 3 ? 3 : 2;\n        return `<h${level}>${escapeBlogHtml(text)}</h${level}>`;\n      }\n      return `<p>${escapeBlogHtml(text)}</p>`;\n    })\n    .join(\"\");\n};\n\nconst setBlogText = (selector, value) => {\n  const element = document.querySelector(selector);\n  if (element) element.textContent = asBlogText(value);\n};\n\nif (selectedBlogPost) {\n  if (requestedPostSlug && requestedPostSlug !== selectedBlogPost.slug) {\n    const canonical = new URL(window.location.href);\n    canonical.pathname = `/blog/${encodeURIComponent(selectedBlogPost.slug)}`;\n    canonical.searchParams.delete(\"post\");\n    canonical.searchParams.delete(\"slug\");\n    window.history.replaceState({}, \"\", canonical);\n  }\n  document.title = `${selectedBlogPost.title} | Digital Commerce Coalition`;\n  document\n    .querySelector(\"#blog-meta-description\")\n    ?.setAttribute(\"content\", selectedBlogPost.excerpt);\n\n  setBlogText(\n    \"#blog-post-category\",\n    selectedBlogPost.category || \"Article\",\n  );\n  setBlogText(\"#blog-post-title\", selectedBlogPost.title);\n  setBlogText(\"#blog-post-excerpt\", selectedBlogPost.excerpt);\n  setBlogText(\"#blog-post-author\", selectedBlogPost.author ? `By ${selectedBlogPost.author}` : \"\");\n  setBlogText(\"#blog-post-date\", selectedBlogPost.date);\n  const hasLegacyBody =\n    selectedBlogPost.body && typeof selectedBlogPost.body === \"object\";\n  setBlogText(\n    \"#blog-post-reading-time\",\n    hasLegacyBody ? \"4 min read\" : selectedBlogPost.readingTime,\n  );\n  const image = document.querySelector(\"#blog-post-image\");\n  if (image) {\n    image.src = selectedBlogPost.image;\n    image.alt = selectedBlogPost.imageAlt || selectedBlogPost.title || \"\";\n  }\n\n  const paragraphContainer = document.querySelector(\"#blog-post-paragraphs\");\n  const providedBody = asBlogText(selectedBlogPost.bodyHtml);\n  const hasUsableBody = providedBody && providedBody !== \"[object Object]\";\n  const legacyBody = legacyRichTextToHtml(selectedBlogPost.body);\n  if (paragraphContainer) {\n    paragraphContainer.innerHTML = hasUsableBody ? providedBody : legacyBody;\n  }\n\n  const toc = document.querySelector(\"#blog-post-toc\");\n  const headings = paragraphContainer?.querySelectorAll(\"h2, h3\") || [];\n  headings.forEach((heading, index) => {\n    heading.id = heading.id || `article-section-${index + 1}`;\n    const link = document.createElement(\"a\");\n    link.href = `#${heading.id}`;\n    link.textContent = heading.textContent || `Section ${index + 1}`;\n    toc?.append(link);\n  });\n\n  // Render related posts in grid\n  const relatedGrid = document.querySelector(\"#blog-related-grid\");\n  if (relatedGrid && typeof createBlogCard === \"function\") {\n    relatedGrid.innerHTML = \"\";\n    const otherPosts = dccBlogPosts.filter((p) => p.slug !== selectedBlogPost.slug).slice(0, 3);\n    otherPosts.forEach((post, index) => {\n      relatedGrid.append(createBlogCard(post, index));\n    });\n  }\n\n  const linkedInShare = document.querySelector(\"#blog-linkedin-share\");\n  if (linkedInShare) {\n    linkedInShare.href = `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(window.location.href)}`;\n  }\n\n  const copyButton = document.querySelector(\"#blog-copy-link\");\n  copyButton?.addEventListener(\"click\", async () => {\n    const status = document.querySelector(\"#blog-copy-status\");\n    try {\n      await navigator.clipboard.writeText(window.location.href);\n      copyButton.textContent = \"Copied\";\n      if (status) status.textContent = \"Link copied.\";\n    } catch {\n      if (status) status.textContent = \"Copy the address from your browser.\";\n    }\n  });\n}\n\n// Reading progress bar calculation\nwindow.addEventListener(\"scroll\", () => {\n  const progressBar = document.querySelector(\"#blog-reading-progress-bar\");\n  if (!progressBar) return;\n  const totalHeight = document.body.scrollHeight - window.innerHeight;\n  const progress = totalHeight > 0 ? window.scrollY / totalHeight : 0;\n  progressBar.style.transform = `scaleX(${Math.min(1, Math.max(0, progress))})`;\n});\n",
  "blog-trust.js": "const trustArticle = dccBlogPosts.find(\n  (post) => post.slug === \"building-trust-into-everyday-digital-commerce\",\n);\n\nconst setTrustText = (selector, value) => {\n  const element = document.querySelector(selector);\n  if (element) element.textContent = value || \"\";\n};\n\nif (trustArticle) {\n  document.title = `${trustArticle.title} | Digital Commerce Coalition`;\n  document\n    .querySelector(\"#trust-meta-description\")\n    ?.setAttribute(\"content\", trustArticle.excerpt);\n\n  setTrustText(\"#trust-author\", trustArticle.author);\n  setTrustText(\"#trust-date\", trustArticle.date);\n  setTrustText(\"#trust-reading-time\", trustArticle.readingTime);\n  setTrustText(\"#trust-excerpt\", trustArticle.excerpt);\n  setTrustText(\"#trust-intro\", trustArticle.intro);\n  setTrustText(\"#trust-paragraph-one\", trustArticle.paragraphs?.[0]);\n  setTrustText(\"#trust-paragraph-two\", trustArticle.paragraphs?.[1]);\n  setTrustText(\"#trust-paragraph-three\", trustArticle.paragraphs?.[2]);\n\n  const image = document.querySelector(\"#trust-image\");\n  if (image) {\n    image.src = trustArticle.image;\n    image.alt = trustArticle.imageAlt || \"\";\n  }\n\n  const takeawayList = document.querySelector(\"#trust-takeaway-list\");\n  trustArticle.takeaways?.forEach((takeaway, index) => {\n    const item = document.createElement(\"li\");\n    item.style.setProperty(\"--takeaway-index\", index);\n\n    const number = document.createElement(\"span\");\n    number.textContent = String(index + 1).padStart(2, \"0\");\n\n    const text = document.createElement(\"p\");\n    text.textContent = takeaway;\n\n    item.append(number, text);\n    takeawayList?.append(item);\n  });\n}\n",
  "events-data.js": "/*\n * Add event entries to the relevant list below. Empty lists automatically show\n * the designed \"more soon\" states on the Events page.\n *\n * Example:\n * {\n *   slug: \"event-name\",\n *   day: \"18\",\n *   month: \"September\",\n *   year: \"2026\",\n *   format: \"Roundtable\",\n *   title: \"Event title\",\n *   summary: \"A short description of the event.\",\n *   location: \"New Delhi\",\n *   image: \"./assets/events/event-name.jpg\",\n *   imageAlt: \"Participants at the event\",\n *   href: \"/events/event-name\",\n *   description: \"A longer description for the internal event page.\",\n *   topics: [\"Topic one\", \"Topic two\", \"Topic three\"],\n *   linkLabel: \"Read more\"\n * }\n */\nconst dccEvents = { upcoming: [], past: [] };\n\nconst createEventCard = (event, index, type) => {\n  const article = document.createElement(\"article\");\n  article.className = \"event-card\";\n  article.style.setProperty(\"--event-card-index\", index);\n\n  const media = document.createElement(\"div\");\n  media.className = \"event-card-media\";\n\n  if (event.image) {\n    const image = document.createElement(\"img\");\n    image.src = event.image;\n    image.alt = event.imageAlt || \"\";\n    image.loading = \"lazy\";\n    media.append(image);\n  } else {\n    const placeholder = document.createElement(\"div\");\n    placeholder.className = \"event-card-image-placeholder\";\n    placeholder.setAttribute(\"aria-hidden\", \"true\");\n\n    const placeholderLabel = document.createElement(\"span\");\n    placeholderLabel.textContent = \"DCC\";\n    placeholder.append(placeholderLabel);\n    media.append(placeholder);\n  }\n\n  const content = document.createElement(\"div\");\n  content.className = \"event-card-content\";\n\n  const date = document.createElement(\"p\");\n  date.className = \"event-card-date\";\n  date.textContent =\n    event.dateLabel ||\n    [event.month, event.day ? `${event.day},` : \"\", event.year]\n      .filter(Boolean)\n      .join(\" \");\n\n  const meta = document.createElement(\"p\");\n  meta.className = \"event-card-meta\";\n  meta.textContent = [event.format, event.location].filter(Boolean).join(\" · \");\n\n  const title = document.createElement(\"h3\");\n  title.textContent = event.title || \"Coalition event\";\n\n  const summary = document.createElement(\"p\");\n  summary.className = \"event-card-summary\";\n  summary.textContent = event.summary || \"\";\n\n  content.append(date);\n  if (meta.textContent) content.append(meta);\n  content.append(title);\n  if (event.summary) content.append(summary);\n\n  if (event.href) {\n    const link = document.createElement(\"a\");\n    link.className = \"event-card-link\";\n    link.href = event.href;\n\n    const linkLabel = document.createElement(\"span\");\n    linkLabel.className = \"event-card-link-label\";\n    linkLabel.textContent =\n      event.linkLabel || (type === \"past\" ? \"Read more\" : \"View event\");\n\n    const arrow = document.createElement(\"span\");\n    arrow.className = \"event-card-arrow\";\n    arrow.setAttribute(\"aria-hidden\", \"true\");\n    arrow.textContent = \"↗\";\n    link.append(linkLabel, arrow);\n    content.append(link);\n  }\n\n  article.append(media, content);\n  return article;\n};\n\nconst renderEventGroup = (type) => {\n  const events = dccEvents[type];\n  const list = document.querySelector(`#${type}-event-list`);\n  const emptyState = document.querySelector(`#${type}-empty-state`);\n\n  if (!list || !emptyState || !Array.isArray(events) || events.length === 0) {\n    return;\n  }\n\n  const fragment = document.createDocumentFragment();\n  events.forEach((event, index) => {\n    fragment.append(createEventCard(event, index, type));\n  });\n\n  list.append(fragment);\n  list.hidden = false;\n  emptyState.hidden = true;\n};\n\nrenderEventGroup(\"upcoming\");\nrenderEventGroup(\"past\");\n",
  "event-detail.js": "const allDccEvents = [\n  ...dccEvents.upcoming.map((event) => ({ ...event, status: \"Upcoming event\" })),\n  ...dccEvents.past.map((event) => ({ ...event, status: \"Past event\" })),\n];\n\nconst eventParams = new URLSearchParams(window.location.search);\nconst eventPathParts = window.location.pathname.split(\"/\").filter(Boolean);\nconst requestedEventSlug = eventParams.get(\"event\") ||\n  (eventPathParts[0] === \"events\" && eventPathParts[1] ? decodeURIComponent(eventPathParts[1]) : null);\nconst selectedDccEvent =\n  allDccEvents.find((event) => event.slug === requestedEventSlug || event.previousSlugs?.includes(requestedEventSlug)) ||\n  allDccEvents[0];\n\nconst getEventDate = (event) =>\n  event.dateLabel ||\n  [event.month, event.day ? `${event.day},` : \"\", event.year]\n    .filter(Boolean)\n    .join(\" \");\n\nconst setText = (selector, value) => {\n  const element = document.querySelector(selector);\n  if (element) element.textContent = value || \"\";\n};\n\nif (selectedDccEvent) {\n  if (requestedEventSlug && requestedEventSlug !== selectedDccEvent.slug) {\n    const canonical = new URL(window.location.href);\n    canonical.pathname = `/events/${encodeURIComponent(selectedDccEvent.slug)}`;\n    canonical.searchParams.delete(\"event\");\n    canonical.searchParams.delete(\"slug\");\n    window.history.replaceState({}, \"\", canonical);\n  }\n  const eventDate = getEventDate(selectedDccEvent);\n\n  document.title = `${selectedDccEvent.title} | Digital Commerce Coalition`;\n  document\n    .querySelector(\"#event-meta-description\")\n    ?.setAttribute(\"content\", selectedDccEvent.summary);\n\n  setText(\"#event-detail-status\", selectedDccEvent.status);\n  setText(\"#event-detail-title\", selectedDccEvent.title);\n  setText(\"#event-detail-summary\", selectedDccEvent.summary);\n  setText(\"#event-detail-about-eyebrow\", selectedDccEvent.aboutEyebrow || \"About the event\");\n  setText(\"#event-detail-about-heading\", selectedDccEvent.aboutHeading || \"Bringing shared priorities into focus.\");\n  setText(\"#event-detail-topics-heading\", selectedDccEvent.topicsHeading || \"What the conversation explores\");\n  setText(\"#event-detail-date\", eventDate);\n  setText(\"#event-detail-location\", selectedDccEvent.location);\n  const description = document.querySelector(\"#event-detail-description\");\n  if (description) description.innerHTML = selectedDccEvent.bodyHtml || \"\";\n  setText(\"#event-fact-date\", eventDate);\n  setText(\"#event-fact-location\", selectedDccEvent.location);\n  setText(\"#event-fact-format\", selectedDccEvent.format);\n\n  const image = document.querySelector(\"#event-detail-image\");\n  if (image) {\n    image.src = selectedDccEvent.image;\n    image.alt = selectedDccEvent.imageAlt || \"\";\n  }\n\n  const topicList = document.querySelector(\"#event-detail-topics\");\n  selectedDccEvent.topics?.forEach((topic) => {\n    const item = document.createElement(\"li\");\n    item.textContent = topic;\n    topicList?.append(item);\n  });\n}\n",
  "press-data.js": "/*\n * Replace these sample entries with real media coverage when it is ready.\n * The neutral example.com URL preserves the external-link interaction without\n * publishing a real article or publication.\n */\nconst dccPressCoverage = [];\n\nconst createPressCard = (coverage, index) => {\n  const card = document.createElement(\"a\");\n  card.className = \"press-card\";\n  card.href = `/press/${encodeURIComponent(coverage.slug)}`;\n  card.style.setProperty(\"--press-card-index\", index);\n  card.setAttribute(\n    \"aria-label\",\n    `Read ${coverage.title}`,\n  );\n\n  const publication = document.createElement(\"p\");\n  publication.className = \"press-publication\";\n  publication.textContent = coverage.publication;\n\n  const title = document.createElement(\"h2\");\n  title.textContent = coverage.title;\n\n  const footer = document.createElement(\"div\");\n  footer.className = \"press-card-footer\";\n\n  const date = document.createElement(\"p\");\n  date.textContent = coverage.date;\n\n  const action = document.createElement(\"span\");\n  action.className = \"press-read-more\";\n\n  const actionLabel = document.createElement(\"span\");\n  actionLabel.className = \"press-read-more-label\";\n  actionLabel.textContent = \"Read more\";\n\n  const arrow = document.createElement(\"span\");\n  arrow.className = \"press-read-more-arrow\";\n  arrow.setAttribute(\"aria-hidden\", \"true\");\n  arrow.textContent = \"→\";\n  action.append(actionLabel, arrow);\n\n  footer.append(date, action);\n  card.append(publication, title, footer);\n  return card;\n};\n\nconst renderPressCoverage = () => {\n  const list = document.querySelector(\"#press-coverage-list\");\n  if (!list) return;\n\n  const fragment = document.createDocumentFragment();\n  dccPressCoverage.forEach((coverage, index) => {\n    fragment.append(createPressCard(coverage, index));\n  });\n  list.append(fragment);\n};\n\nrenderPressCoverage();\n",
  "publications-data.js": "const dccPublications = [];\n\nconst createPublicationCover = (publication, compact = false) => {\n  const cover = document.createElement(\"div\");\n  cover.className = `publication-cover publication-cover-${publication.accent}${compact ? \" is-compact\" : \"\"}`;\n\n  const image = document.createElement(\"img\");\n  image.src = publication.coverImage;\n  image.alt = \"\";\n\n  const veil = document.createElement(\"span\");\n  veil.className = \"publication-cover-veil\";\n  veil.setAttribute(\"aria-hidden\", \"true\");\n\n  const logo = document.createElement(\"img\");\n  logo.className = \"publication-cover-logo\";\n  logo.src = \"./assets/Dcc_logo.svg\";\n  logo.alt = \"\";\n\n  const label = document.createElement(\"span\");\n  label.className = \"publication-cover-label\";\n  label.textContent = publication.type;\n\n  const title = document.createElement(\"strong\");\n  title.textContent = publication.title;\n\n  const date = document.createElement(\"span\");\n  date.className = \"publication-cover-date\";\n  date.textContent = publication.date;\n\n  cover.append(image, veil, logo, label, title, date);\n  return cover;\n};\n\nconst createPublicationCard = (publication) => {\n  const article = document.createElement(\"article\");\n  article.className = \"publication-card\";\n\n  const media = document.createElement(\"div\");\n  media.className = \"publication-card-media\";\n  media.append(createPublicationCover(publication, true));\n\n  const body = document.createElement(\"div\");\n  body.className = \"publication-card-body\";\n\n  const meta = document.createElement(\"p\");\n  meta.className = \"publication-meta\";\n  meta.textContent = `${publication.type} · ${publication.date}`;\n\n  const title = document.createElement(\"h2\");\n  title.textContent = publication.title;\n\n  const description = document.createElement(\"p\");\n  description.className = \"publication-card-description\";\n  description.textContent = publication.description;\n\n  const actions = document.createElement(\"div\");\n  actions.className = \"publication-card-actions report-card-actions\";\n\n  const download = document.createElement(\"a\");\n  download.className = \"report-download-link\";\n  download.href = `/publications/${encodeURIComponent(publication.slug)}`;\n  download.setAttribute(\"aria-label\", `Read ${publication.title}`);\n  download.innerHTML =\n    '<span>Read publication</span><span class=\"report-download-icon\" aria-hidden=\"true\">→</span>';\n\n  actions.append(download);\n  body.append(meta, title, description, actions);\n  article.append(media, body);\n  return article;\n};\n\nconst renderPublicationLibrary = () => {\n  const list = document.querySelector(\"#publication-list\");\n  if (!list) return;\n\n  const fragment = document.createDocumentFragment();\n  dccPublications.forEach((publication) => {\n    fragment.append(createPublicationCard(publication));\n  });\n  list.replaceChildren(fragment);\n};\n\nconst renderPublicationDetail = () => {\n  const detail = document.querySelector(\"#publication-detail\");\n  if (!detail) return;\n\n  const params = new URLSearchParams(window.location.search);\n  const pathParts = window.location.pathname.split(\"/\").filter(Boolean);\n  const requestedSlug = params.get(\"slug\") ||\n    (pathParts[0] === \"publications\" && pathParts[1] ? decodeURIComponent(pathParts[1]) : null);\n  const publication = dccPublications.find(\n    (item) => item.slug === requestedSlug || item.previousSlugs?.includes(requestedSlug),\n  );\n  if (!publication) {\n    window.location.replace(\"/publications\");\n    return;\n  }\n\n  if (requestedSlug && requestedSlug !== publication.slug) {\n    const canonical = new URL(window.location.href);\n    canonical.pathname = `/publications/${encodeURIComponent(publication.slug)}`;\n    canonical.searchParams.delete(\"slug\");\n    canonical.searchParams.delete(\"publication\");\n    window.history.replaceState({}, \"\", canonical);\n  }\n\n  document.title = `${publication.title} | Digital Commerce Coalition`;\n  document\n    .querySelector('meta[name=\"description\"]')\n    ?.setAttribute(\"content\", publication.description);\n\n  const back = document.querySelector(\"#publication-back-link\");\n  if (back) back.href = \"/publications\";\n\n  const type = document.querySelector(\"#publication-detail-type\");\n  const title = document.querySelector(\"#publication-detail-title\");\n  const description = document.querySelector(\"#publication-detail-description\");\n  const date = document.querySelector(\"#publication-detail-date\");\n  const pages = document.querySelector(\"#publication-detail-pages\");\n  const themes = document.querySelector(\"#publication-detail-themes\");\n  const body = document.querySelector(\"#publication-detail-body\");\n  const bodyFallback = document.querySelector(\"#publication-detail-body-fallback\");\n  const cover = document.querySelector(\"#publication-detail-cover\");\n  const download = document.querySelector(\"#publication-detail-download\");\n\n  if (type) type.textContent = publication.type;\n  if (title) title.textContent = publication.title;\n  if (description) description.textContent = publication.description;\n  if (body && publication.bodyHtml && publication.bodyHtml !== \"<p></p>\") {\n    body.innerHTML = publication.bodyHtml;\n    if (bodyFallback) bodyFallback.hidden = true;\n  }\n  if (date) date.textContent = publication.date;\n  if (pages) pages.textContent = publication.pages;\n  if (themes) {\n    themes.replaceChildren(\n      ...publication.themes.map((theme) => {\n        const item = document.createElement(\"li\");\n        item.textContent = theme;\n        return item;\n      }),\n    );\n  }\n  if (cover) cover.replaceChildren(createPublicationCover(publication));\n  if (download) {\n    if (publication.pdf) {\n      download.href = publication.pdf;\n      download.download = \"\";\n      download.setAttribute(\"aria-label\", `Download ${publication.title} PDF`);\n    } else {\n      download.hidden = true;\n    }\n  }\n\n  const related = document.querySelector(\"#related-publications\");\n  if (related) {\n    related.replaceChildren(\n      ...dccPublications\n        .filter((item) => item.slug !== publication.slug)\n        .slice(0, 2)\n        .map(createPublicationCard),\n    );\n  }\n};\n\nrenderPublicationLibrary();\nrenderPublicationDetail();\n",
  "reports-data.js": "const dccReports = [];\n\nconst createReportCard = (report) => {\n  const article = document.createElement(\"article\");\n  article.className = \"publication-card report-card\";\n\n  const media = document.createElement(\"div\");\n  media.className = \"publication-card-media\";\n\n  const image = document.createElement(\"img\");\n  image.className = \"report-card-image\";\n  image.src = report.coverImage;\n  image.alt = \"\";\n  media.append(image);\n\n  const body = document.createElement(\"div\");\n  body.className = \"publication-card-body\";\n\n  const meta = document.createElement(\"p\");\n  meta.className = \"publication-meta\";\n  meta.textContent = `${report.type} · ${report.date}`;\n\n  const title = document.createElement(\"h2\");\n  title.textContent = report.title;\n\n  const description = document.createElement(\"p\");\n  description.className = \"publication-card-description\";\n  description.innerHTML = report.description;\n\n  const actions = document.createElement(\"div\");\n  actions.className = \"publication-card-actions report-card-actions\";\n\n  const download = document.createElement(\"a\");\n  download.className = \"report-download-link\";\n  download.href = `/reports/${encodeURIComponent(report.slug)}`;\n  download.setAttribute(\"aria-label\", `View ${report.title}`);\n  download.innerHTML =\n    '<span>View report</span><span class=\"report-download-icon\" aria-hidden=\"true\">→</span>';\n\n  actions.append(download);\n  body.append(meta, title, description, actions);\n  article.append(media, body);\n  return article;\n};\n\nconst renderReports = () => {\n  const list = document.querySelector(\"#report-list\");\n  if (!list) return;\n\n  const fragment = document.createDocumentFragment();\n  dccReports.forEach((report) => fragment.append(createReportCard(report)));\n  list.replaceChildren(fragment);\n};\n\nrenderReports();\n",
  "script.js": "const workBubbles = Array.from(document.querySelectorAll(\"[data-work-bubble]\"));\n\nif (workBubbles.length === 4) {\n  const slotClasses = [\n    \"is-center\",\n    \"is-left\",\n    \"is-right\",\n    \"is-hidden\",\n    \"is-hidden-left\",\n    \"is-hidden-right\",\n  ];\n  const hiddenSlots = [\"is-hidden\", \"is-hidden-left\", \"is-hidden-right\"];\n  const stackedDial = window.matchMedia(\"(max-width: 759px)\");\n  const workScroll = document.querySelector(\".work-scroll\");\n  const workSection = document.querySelector(\".work\");\n  const diamondRails = document.querySelector(\".diamond-rails\");\n  let activeIndex = -1;\n  let frame = null;\n  let railsPinned = false;\n\n  const syncDiamondRails = () => {\n    if (!diamondRails || !workScroll || !workSection || stackedDial.matches) {\n      diamondRails?.classList.remove(\"is-pinned\");\n      railsPinned = false;\n      return;\n    }\n\n    const rootStyles = window.getComputedStyle(document.documentElement);\n    const diamondGap =\n      Number.parseFloat(rootStyles.getPropertyValue(\"--diamond-gap\")) || 0;\n    const stickyTop =\n      Number.parseFloat(window.getComputedStyle(workSection).top) || 0;\n    const workRect = workScroll.getBoundingClientRect();\n    const rawOffset = stickyTop - workRect.top;\n    const maxOffset = Math.max(\n      0,\n      workRect.height -\n        workSection.getBoundingClientRect().height,\n    );\n    const shouldPin = rawOffset > 0 && rawOffset < maxOffset;\n\n    if (diamondGap > 0 && !railsPinned && shouldPin) {\n      const mainTop = diamondRails.parentElement.getBoundingClientRect().top;\n      const phase =\n        ((((mainTop + 22 - stickyTop) % diamondGap) + diamondGap) % diamondGap);\n\n      diamondRails.style.setProperty(\n        \"--pinned-diamond-phase\",\n        `${Number(phase.toFixed(3))}px`,\n      );\n    }\n\n    if (shouldPin === railsPinned) return;\n\n    railsPinned = shouldPin;\n    diamondRails.classList.toggle(\"is-pinned\", shouldPin);\n  };\n\n  const getSlot = (index, currentIndex) => {\n    const offset = (index - currentIndex + workBubbles.length) % workBubbles.length;\n\n    if (offset === 0) return \"is-center\";\n    if (offset === 1) return \"is-right\";\n    if (offset === workBubbles.length - 1) return \"is-left\";\n    return \"is-hidden\";\n  };\n\n  const getCurrentSlot = (bubble) =>\n    slotClasses.find((slotClass) => bubble.classList.contains(slotClass));\n\n  const isHiddenSlot = (slot) => hiddenSlots.includes(slot);\n\n  const getHiddenEntrySlot = (direction) =>\n    direction < 0 ? \"is-hidden-left\" : \"is-hidden-right\";\n\n  const getHiddenExitSlot = (currentSlot, direction) => {\n    if (currentSlot === \"is-left\" || direction > 0) return \"is-hidden-left\";\n    if (currentSlot === \"is-right\" || direction < 0) return \"is-hidden-right\";\n    return getHiddenEntrySlot(direction);\n  };\n\n  const applySlot = (bubble, slot, { instant = false } = {}) => {\n    if (instant) bubble.classList.add(\"no-motion\");\n\n    bubble.classList.remove(...slotClasses);\n    bubble.classList.add(slot);\n    bubble.setAttribute(\n      \"aria-hidden\",\n      !stackedDial.matches && isHiddenSlot(slot) ? \"true\" : \"false\",\n    );\n\n    if (!instant) return;\n    void bubble.offsetHeight;\n    bubble.classList.remove(\"no-motion\");\n  };\n\n  const getActiveIndex = () => {\n    if (!workScroll || !workSection || stackedDial.matches) return 0;\n\n    const rect = workScroll.getBoundingClientRect();\n    const stickyTop = Number.parseFloat(window.getComputedStyle(workSection).top) || 0;\n    const workHeight = workSection.getBoundingClientRect().height;\n    const scrollDistance = workHeight * 0.75;\n    const startDelay = workHeight * 0.18;\n    const progress = Math.min(\n      1,\n      Math.max(0, (stickyTop - rect.top - startDelay) / scrollDistance),\n    );\n\n    if (progress <= 0.005) return 0;\n\n    return Math.min(\n      workBubbles.length - 1,\n      Math.ceil(progress * (workBubbles.length - 1)),\n    );\n  };\n\n  const renderDial = () => {\n    const nextActive = getActiveIndex();\n\n    if (nextActive === activeIndex && !stackedDial.matches) return;\n    const direction = activeIndex < 0 ? 1 : Math.sign(nextActive - activeIndex) || 1;\n    activeIndex = nextActive;\n    const hiddenEntrySlot = getHiddenEntrySlot(direction);\n\n    workBubbles.forEach((bubble, index) => {\n      const currentSlot = getCurrentSlot(bubble) || hiddenEntrySlot;\n      const nextSlot = getSlot(index, activeIndex);\n\n      if (isHiddenSlot(nextSlot)) {\n        applySlot(\n          bubble,\n          isHiddenSlot(currentSlot)\n            ? hiddenEntrySlot\n            : getHiddenExitSlot(currentSlot, direction),\n          { instant: isHiddenSlot(currentSlot) && !stackedDial.matches },\n        );\n        return;\n      }\n\n      if (isHiddenSlot(currentSlot) && !stackedDial.matches) {\n        applySlot(bubble, hiddenEntrySlot, { instant: true });\n        window.requestAnimationFrame(() => {\n          applySlot(bubble, nextSlot);\n        });\n        return;\n      }\n\n      applySlot(bubble, nextSlot);\n    });\n  };\n\n  const scheduleRender = () => {\n    if (frame) return;\n    frame = window.requestAnimationFrame(() => {\n      frame = null;\n      syncDiamondRails();\n      renderDial();\n    });\n  };\n\n  syncDiamondRails();\n  renderDial();\n  window.addEventListener(\"scroll\", scheduleRender, { passive: true });\n  window.addEventListener(\"resize\", () => {\n    syncDiamondRails();\n    scheduleRender();\n  });\n  window.addEventListener(\"load\", syncDiamondRails);\n  document.fonts?.ready?.then(syncDiamondRails);\n  stackedDial.addEventListener(\"change\", () => {\n    syncDiamondRails();\n    scheduleRender();\n  });\n}\n\nconst reducedMotion = window.matchMedia(\"(prefers-reduced-motion: reduce)\");\n\nconst wrapWordsForReveal = (element) => {\n  if (element.dataset.textRevealReady === \"true\") return;\n\n  const counter = { value: 0 };\n\n  const wrapTextNode = (textNode) => {\n    const parts = textNode.textContent.split(/(\\s+)/);\n    const fragment = document.createDocumentFragment();\n\n    parts.forEach((part) => {\n      if (!part) return;\n\n      if (/^\\s+$/.test(part)) {\n        fragment.append(part);\n        return;\n      }\n\n      const word = document.createElement(\"span\");\n      word.className = \"reveal-word\";\n      word.style.setProperty(\"--word-index\", counter.value);\n      word.textContent = part;\n      counter.value += 1;\n      fragment.append(word);\n    });\n\n    textNode.replaceWith(fragment);\n  };\n\n  const walk = (node) => {\n    if (node.nodeType === Node.TEXT_NODE) {\n      if (node.textContent.trim()) wrapTextNode(node);\n      return;\n    }\n\n    const display = window.getComputedStyle(node).display;\n    const keepsDirectTextTogether =\n      display === \"flex\" || display === \"inline-flex\";\n\n    Array.from(node.childNodes).forEach((child) => {\n      if (keepsDirectTextTogether && child.nodeType === Node.TEXT_NODE) return;\n      walk(child);\n    });\n  };\n\n  walk(element);\n  element.dataset.textRevealReady = \"true\";\n};\n\nconst setupRevealAnimations = () => {\n  const textTargets = Array.from(\n    document.querySelectorAll(\n      [\n        \".hero-copy h1\",\n        \".about-copy h2\",\n        \".about-copy p\",\n        \".section-kicker\",\n        \".focus-card h3\",\n        \".focus-card p\",\n        \".work-bubble h2\",\n        \".work-bubble h3\",\n        \".work-bubble p\",\n        \".contact a\",\n        \".events-hero h1\",\n        \".events-hero .events-eyebrow\",\n        \".events-intro\",\n        \".events-section-heading .events-eyebrow\",\n        \".events-section-heading h2\",\n        \".events-empty-copy h3\",\n        \".events-empty-copy > p\",\n        \".archive-copy h3\",\n        \".archive-copy > p\",\n        \".events-contact .events-eyebrow\",\n        \".events-contact h2\",\n        \".events-contact a\",\n        \".event-detail-copy .events-eyebrow\",\n        \".event-detail-title\",\n        \".event-detail-summary\",\n        \".event-detail-article .events-eyebrow\",\n        \".event-detail-article h2\",\n        \".event-detail-article > p\",\n        \".event-topics h3\",\n        \".event-topic-list li\",\n        \".event-facts-title\",\n        \".event-facts dd\",\n        \".event-detail-contact .events-eyebrow\",\n        \".event-detail-contact h2\",\n        \".event-detail-contact a\",\n        \".blog-section-heading .blog-eyebrow\",\n        \".blog-section-heading h2\",\n        \".blog-card-label\",\n        \".blog-card h2\",\n        \".blog-card-excerpt\",\n        \".blog-card-footer\",\n        \".blog-contact .blog-eyebrow\",\n        \".blog-contact h2\",\n        \".blog-contact a\",\n        \".blog-post-hero .blog-eyebrow\",\n        \".blog-post-hero h1\",\n        \".blog-post-excerpt\",\n        \".blog-post-meta\",\n        \".blog-post-paragraphs p\",\n        \".blog-post-contact .blog-eyebrow\",\n        \".blog-post-contact h2\",\n        \".blog-post-contact a\",\n        \".press-section-heading .press-eyebrow\",\n        \".press-section-heading h2\",\n        \".press-card .press-publication\",\n        \".press-card h2\",\n        \".press-card-footer\",\n        \".press-contact .press-eyebrow\",\n        \".press-contact h2\",\n        \".press-contact a\",\n        \".publications-section-heading .publications-eyebrow\",\n        \".publications-section-heading h2\",\n        \".publication-card .publication-meta\",\n        \".publication-card h2\",\n        \".publication-card-description\",\n        \".publication-card-actions\",\n        \".publications-contact .publications-eyebrow\",\n        \".publications-contact h2\",\n        \".publications-contact a\",\n        \".publication-detail-copy .publications-eyebrow\",\n        \".publication-detail-copy h1\",\n        \".publication-detail-description\",\n        \".publication-facts dd\",\n        \".publication-about .publications-eyebrow\",\n        \".publication-about h2\",\n        \".publication-about-copy > p\",\n        \".publication-theme-list li\",\n        \".trust-hero .blog-eyebrow\",\n        \".trust-hero h1\",\n        \".trust-meta\",\n        \".trust-deck p\",\n        \".trust-body-aside .blog-eyebrow\",\n        \".trust-body-aside > p\",\n        \".trust-lead\",\n        \".trust-reading-section h2\",\n        \".trust-reading-section div > p\",\n        \".trust-quote\",\n        \".trust-takeaways .blog-eyebrow\",\n        \".trust-takeaways h2\",\n        \".trust-takeaways li\",\n        \".trust-next .blog-eyebrow\",\n        \".trust-next h2\",\n        \".trust-next a\",\n      ].join(\", \"),\n    ),\n  );\n\n  const revealTargets = Array.from(\n    document.querySelectorAll(\n      [\n        \".hero-copy\",\n        \".hero-art\",\n        \".about-copy\",\n        \".about-visual\",\n        \".section-heading\",\n        \".focus-card\",\n        \".council .section-kicker\",\n        \".logo-row\",\n        \".contact .section-kicker\",\n        \".contact a\",\n        \".site-footer > div\",\n        \".events-hero-copy\",\n        \".events-hero-art\",\n        \".events-section-heading\",\n        \".events-empty-state\",\n        \".past-events-archive\",\n        \".events-contact .events-eyebrow\",\n        \".events-contact-row\",\n        \".event-detail-copy\",\n        \".event-detail-image-wrap\",\n        \".event-detail-article\",\n        \".event-detail-aside\",\n        \".event-detail-contact\",\n        \".blog-section-heading\",\n        \".blog-card\",\n        \".blog-contact\",\n        \".blog-post-hero .blog-back-link\",\n        \".blog-post-image-wrap\",\n        \".blog-post-content\",\n        \".blog-post-contact\",\n        \".press-section-heading\",\n        \".press-card\",\n        \".press-contact\",\n        \".publications-section-heading\",\n        \".publication-card\",\n        \".publications-contact\",\n        \".publication-back-link\",\n        \".publication-detail-copy\",\n        \".publication-detail-cover\",\n        \".publication-about > div\",\n        \".trust-hero-copy\",\n        \".trust-hero-image\",\n        \".trust-deck\",\n        \".trust-body-aside\",\n        \".trust-body-content\",\n        \".trust-takeaways\",\n        \".trust-next\",\n      ].join(\", \"),\n    ),\n  );\n\n  document.querySelectorAll(\".about-visual, .focus-card\").forEach((element, index) => {\n    element.style.setProperty(\"--reveal-delay\", `${index * 90}ms`);\n  });\n\n  if (reducedMotion.matches) {\n    [...revealTargets, ...textTargets].forEach((element) => {\n      element.classList.add(\"is-visible\");\n    });\n    return;\n  }\n\n  textTargets.forEach((element) => {\n    wrapWordsForReveal(element);\n    element.classList.add(\"text-reveal\");\n  });\n\n  revealTargets.forEach((element) => {\n    element.classList.add(\"reveal\");\n  });\n\n  const animatedTargets = Array.from(new Set([...revealTargets, ...textTargets]));\n\n  if (!(\"IntersectionObserver\" in window)) {\n    animatedTargets.forEach((element) => element.classList.add(\"is-visible\"));\n    return;\n  }\n\n  const revealObserver = new IntersectionObserver(\n    (entries, observer) => {\n      entries.forEach((entry) => {\n        if (!entry.isIntersecting) return;\n\n        entry.target.classList.add(\"is-visible\");\n        observer.unobserve(entry.target);\n      });\n    },\n    {\n      rootMargin: \"0px 0px -12% 0px\",\n      threshold: 0.12,\n    },\n  );\n\n  animatedTargets.forEach((element) => revealObserver.observe(element));\n};\n\nconst setupMobileMenu = () => {\n  const header = document.querySelector(\".site-header\");\n  const toggle = document.querySelector(\".menu-toggle\");\n  const menu = document.querySelector(\".mobile-menu\");\n\n  if (!header || !toggle || !menu) return;\n\n  const setOpen = (isOpen) => {\n    header.classList.toggle(\"is-menu-open\", isOpen);\n    document.body.classList.toggle(\"is-menu-open\", isOpen);\n    toggle.setAttribute(\"aria-expanded\", String(isOpen));\n    toggle.setAttribute(\"aria-label\", isOpen ? \"Close menu\" : \"Open menu\");\n  };\n\n  toggle.addEventListener(\"click\", () => {\n    setOpen(!header.classList.contains(\"is-menu-open\"));\n  });\n\n  menu.addEventListener(\"click\", (event) => {\n    if (event.target.closest(\"a\")) setOpen(false);\n  });\n\n  window.addEventListener(\"keydown\", (event) => {\n    if (event.key === \"Escape\") setOpen(false);\n  });\n};\n\nsetupRevealAnimations();\nsetupMobileMenu();\n",
  "content-detail.js": "const contentPathParts = window.location.pathname.split(\"/\").filter(Boolean);\nconst contentSection = contentPathParts[0] || \"\";\nconst contentParams = new URLSearchParams(window.location.search);\nconst requestedContentSlug = contentPathParts[1]\n  ? decodeURIComponent(contentPathParts[1])\n  : contentParams.get(\"slug\") || contentParams.get(\"report\") || contentParams.get(\"press\") || contentParams.get(\"release\");\nconst selectedContentItem = dccContentItems.find(\n  (item) => item.slug === requestedContentSlug || item.previousSlugs?.includes(requestedContentSlug),\n);\n\nconst setContentText = (selector, value) => {\n  const element = document.querySelector(selector);\n  if (element) element.textContent = value || \"\";\n};\n\nif (!selectedContentItem) {\n  window.location.replace(contentSection === \"press\" ? \"/press\" : \"/reports\");\n} else {\n  const isPress = selectedContentItem.contentKind === \"press\";\n  const canonicalSection = isPress ? \"press\" : \"reports\";\n  if (requestedContentSlug !== selectedContentItem.slug) {\n    const canonical = new URL(window.location.href);\n    canonical.pathname = `/${canonicalSection}/${encodeURIComponent(selectedContentItem.slug)}`;\n    canonical.searchParams.delete(\"slug\");\n    canonical.searchParams.delete(\"report\");\n    canonical.searchParams.delete(\"press\");\n    canonical.searchParams.delete(\"release\");\n    window.history.replaceState({}, \"\", canonical);\n  }\n\n  document.title = `${selectedContentItem.title} | Digital Commerce Coalition`;\n  setContentText(\"#content-detail-type\", isPress ? \"Press coverage\" : selectedContentItem.type || \"Coalition report\");\n  setContentText(\"#content-detail-title\", selectedContentItem.title);\n  setContentText(\"#content-detail-date\", selectedContentItem.date);\n  setContentText(\"#content-detail-source\", isPress ? selectedContentItem.publication : \"Digital Commerce Coalition\");\n  setContentText(\"#content-detail-back-label\", isPress ? \"All press\" : \"All reports\");\n  setContentText(\"#content-detail-about-title\", isPress ? \"Coverage details\" : \"About this report\");\n\n  const back = document.querySelector(\"#content-detail-back\");\n  if (back) back.href = isPress ? \"/press\" : \"/reports\";\n\n  const description = document.querySelector(\"#content-detail-description\");\n  const body = document.querySelector(\"#content-detail-body\");\n  const itemDescription = selectedContentItem.description ||\n    (isPress ? `${selectedContentItem.publication} featured the Digital Commerce Coalition in this article.` : \"\");\n  if (description) description.innerHTML = itemDescription;\n  if (body) body.innerHTML = itemDescription;\n\n  const media = document.querySelector(\"#content-detail-media\");\n  const image = document.querySelector(\"#content-detail-image\");\n  if (selectedContentItem.coverImage && image) {\n    image.src = selectedContentItem.coverImage;\n    image.alt = selectedContentItem.title || \"\";\n  } else {\n    media?.setAttribute(\"hidden\", \"\");\n    document.querySelector(\"#content-detail\")?.classList.add(\"has-no-media\");\n  }\n\n  const action = document.querySelector(\"#content-detail-action\");\n  const actionLabel = document.querySelector(\"#content-detail-action-label\");\n  const actionUrl = isPress ? selectedContentItem.url : selectedContentItem.pdf;\n  if (action && actionUrl) {\n    action.href = actionUrl;\n    if (isPress) {\n      action.target = \"_blank\";\n      action.rel = \"noopener noreferrer\";\n      if (actionLabel) actionLabel.textContent = \"Read original coverage\";\n    } else {\n      action.download = \"\";\n      if (actionLabel) actionLabel.textContent = \"Download report\";\n    }\n  } else {\n    action?.setAttribute(\"hidden\", \"\");\n  }\n}\n"
};
